<!-- Generated by `npx @musikhood-dev/auth-client init` — this file is yours, edit freely. -->
<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useAuth, useMfa } from '@musikhood-dev/auth-client/vue'

import AuthModal from '@@/components/auth/AuthModal.vue'
import { reportAuthError } from '@@/lib/auth'
import { formatRetryAfter, isAuthError, MFA_TEXTS } from '@@/lib/mfa'

// Global: the backend answered 403 `mfa_enrollment_required` on a regular request (the
// panel requires 2FA, the user has none). The gate never issues the setup link — the user
// confirms the password, then gets a full navigation to the auth server's /setup-2fa page.
// Not dismissable; the alternative is logging out. Rendered by <AuthMfaDialogs />.
const { stage, enrollmentUrl, requestEnrollment } = useMfa()
const { logout } = useAuth()
const password = ref('')
const error = ref<string | null>(null)
const pending = ref(false)

// Gated on the MFA stage alone: it is set only by a 403 on a live session and reset by
// auth-client on logout / session end (no `isAuthenticated` needed — works outside <AuthBoundary>).
const open = computed(() => stage.value === 'enrollment' && enrollmentUrl.value === null)

// Native `autofocus` does not fire for a dialog opened later — focus the password field.
const formRef = ref<HTMLFormElement | null>(null)
watch(open, (isOpen) => {
  if (isOpen) void nextTick(() => formRef.value?.querySelector<HTMLInputElement>('input')?.focus())
})

async function handleSubmit() {
  if (!password.value || pending.value) return
  error.value = null
  pending.value = true
  try {
    const url = await requestEnrollment(password.value)
    window.location.assign(url)
  } catch (err) {
    pending.value = false
    if (isAuthError(err, 'InvalidCredentialsError')) {
      error.value = MFA_TEXTS.invalidPassword
    } else if (isAuthError(err, 'TooManyAttemptsError')) {
      error.value = formatRetryAfter(err.retryAfter)
    } else if (isAuthError(err, 'MfaAlreadyEnabledError')) {
      error.value = MFA_TEXTS.alreadyEnabled
    } else {
      // Unexpected failure (5xx, network): short inline text + the global report.
      error.value = MFA_TEXTS.enrollmentFailed
      reportAuthError(err, MFA_TEXTS.enrollmentFailed)
    }
  }
}

function handleLogout() {
  password.value = ''
  error.value = null
  void logout().catch((err: unknown) => reportAuthError(err, MFA_TEXTS.logoutFailed))
}
</script>

<template>
  <AuthModal
    :open="open"
    title="Ten panel wymaga 2FA"
    description="Ten panel wymaga weryfikacji dwuetapowej (2FA). Potwierdź hasło, aby przejść do konfiguracji aplikacji uwierzytelniającej."
  >
    <form ref="formRef" class="auth-form" novalidate @submit.prevent="handleSubmit">
      <div class="auth-field">
        <label for="mfa-enrollment-password">Hasło</label>
        <input
          id="mfa-enrollment-password"
          v-model="password"
          type="password"
          autocomplete="current-password"
          :disabled="pending"
          :aria-invalid="error !== null"
        />
        <p v-if="error" role="alert" class="auth-error">{{ error }}</p>
      </div>
      <div class="auth-actions">
        <button type="button" :disabled="pending" @click="handleLogout">Wyloguj się</button>
        <button type="submit" class="auth-submit" :disabled="!password || pending">
          {{ pending ? 'Przygotowywanie…' : 'Przejdź do konfiguracji' }}
        </button>
      </div>
    </form>
  </AuthModal>
</template>
